'use strict';
const C=window.BodyCore,F=window.BodyFocus,R=window.InBodyReport,$=id=>document.getElementById(id);
const STORE='bodyroutine.app.v3',LEGACY='bodyroutine.records.v1';
const titles={report:'인바디 분석',focus:'바디 포커스',dashboard:'대시보드',composition:'체성분 상세',workout:'운동 루틴',history:'변화 기록',settings:'설정 · 데이터'};
const metricMeta={weight:{name:'체중',unit:'kg',color:'#218975',icon:'scale'},muscle:{name:'골격근량',unit:'kg',color:'#7784cf',icon:'muscle'},fat:{name:'체지방률',unit:'%',color:'#d8a06f',icon:'drop'}};
const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',body:'M12 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4M5 10l7-2 7 2M12 8v6M9 21l3-7 3 7',chart:'M4 3v17h17M7 14l4-4 4 2 5-7',workout:'M4 8v8M7 5v14M17 5v14M20 8v8M7 12h10',history:'M3 11a9 9 0 1 1 3 8M3 4v7h7M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',up:'M6 17L18 5M6 5h12v12',down:'M12 4v12M7 11l5 5 5-5M4 17v3h16v-3',upload:'M12 16V4M7 9l5-5 5 5M4 15v5h16v-5',close:'M6 6l12 12M18 6L6 18',check:'M5 12l4 4L19 6',edit:'M14 4l6 6M4 20l5-1L21 7l-5-5L4 14z',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',scale:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2M8 8a5 5 0 0 1 8 0M12 8l2-2',muscle:'M6 8l2-4h4l1 4-3 2 2 3 5-2 3 3-2 5H9l-5-4z',drop:'M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12M9 16a3 3 0 0 0 3 3',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',leaf:'M20 4C5 2 2 13 8 17c5 5 14-1 12-13M5 21l10-10',left:'M15 5l-7 7 7 7',right:'M9 5l7 7-7 7',file:'M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h5',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(value,digits=1){return Number.isFinite(value)?value.toFixed(digits):'—'}
function shortDate(date){return date?date.slice(5).replace('-','.'):'—'}
function longDate(date){if(!date)return '측정 기록 없음';return `${date.slice(0,4)}.${date.slice(5,7)}.${date.slice(8,10)}`}
function dateObj(date){return new Date(`${date}T12:00:00`)}
function dateString(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function shifted(date,days){const d=dateObj(date);d.setDate(d.getDate()+days);return dateString(d)}
function monday(date=C.today()){const d=dateObj(date);return shifted(date,-((d.getDay()+6)%7))}
function cleanPrefs(p={}){if(!p||typeof p!=='object'||Array.isArray(p))p={};return {goal:['balance','loss','gain'].includes(p.goal)?p.goal:'balance',level:p.level==='regular'?'regular':'beginner',days:[2,3,4,5].includes(Number(p.days))?Number(p.days):3,place:p.place==='gym'?'gym':'home',minutes:[20,40,60].includes(Number(p.minutes))?Number(p.minutes):40,equipment:p.place==='gym'?'gym':p.equipment==='band'?'band':'none',pain:p.pain===true}}
const exerciseIds=new Set(Object.values(F.catalog).map(e=>e.id));
function cleanLogs(raw){const out={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return out;for(const [date,entries]of Object.entries(raw).slice(-730)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>C.today()||Number.isNaN(dateObj(date).getTime())||dateString(dateObj(date))!==date||!entries||typeof entries!=='object')continue;const clean={};for(const [id,v]of Object.entries(entries)){if(!exerciseIds.has(id)||!v||typeof v!=='object')continue;const bound=(x,min,max,int=false)=>typeof x==='number'&&Number.isFinite(x)&&x>=min&&x<=max&&(!int||Number.isInteger(x))?x:null;clean[id]={done:v.done===true,sets:bound(v.sets,1,10,true),reps:bound(v.reps,1,100,true),weight:bound(v.weight,0,500),minutes:bound(v.minutes,1,240,true)}}if(Object.keys(clean).length)out[date]=clean}return out}

function cleanFocusPlans(raw){const out={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return out;for(const [date,items]of Object.entries(raw).slice(-730)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(dateObj(date).getTime())||dateString(dateObj(date))!==date||date>shifted(C.today(),365)||!Array.isArray(items))continue;const seen=new Set(),valid=[];for(const item of items.slice(0,100)){if(!item||typeof item!=='object'||!exerciseIds.has(item.id)||F.exerciseKind(item.id)!=='strength'||seen.has(item.id)||!Number.isInteger(item.sets)||item.sets<1||item.sets>6)continue;seen.add(item.id);valid.push({id:item.id,part:Object.hasOwn(F.parts,item.part)?item.part:'core',sets:item.sets});if(valid.length===6)break}if(valid.length)out[date]=valid}return out}
function addFocusExercise(id,part){const a=active();if(a.prefs.pain){toast('운동 가능 범위를 먼저 확인하고 운동 조건을 수정해주세요.');return}const rec=F.recommend(part,effectivePrefs()),ex=rec.exercises.find(ex=>ex.id===id);if(!ex)return;if(baseHasExercise(id)){toast('오늘의 기본 루틴에 이미 포함된 운동이에요.');return}a.focusPlans??={};const plans=a.focusPlans[C.today()]||[];if(plans.some(ex=>ex.id===id)){toast('오늘 루틴에 이미 담긴 운동이에요.');return}if(plans.length>=6){toast('집중 운동은 하루에 최대 6개까지 담을 수 있어요.');return}a.focusPlans[C.today()]=[...plans,{id:ex.id,part:rec.part.id,sets:ex.sets}];persist();render();savedToast('오늘 루틴에 집중 운동을 담았어요.')}
function removeFocusExercise(id,date=C.today()){const a=active();a.focusPlans??={};a.focusPlans[date]=(a.focusPlans[date]||[]).filter(ex=>ex.id!==id);if(!a.focusPlans[date].length)delete a.focusPlans[date];persist();render();savedToast('집중 운동 계획에서 뺐어요. 실제 수행 기록은 유지됩니다.')}

function cleanGoal(g){if(!g||!metricMeta[g.metric])return null;const bounds={weight:[30,250],muscle:[5,100],fat:[3,65]}[g.metric];if(!Number.isFinite(g.target)||g.target<bounds[0]||g.target>bounds[1]||!Number.isFinite(g.startValue)||g.startValue<=0)return null;return {metric:g.metric,target:g.target,startValue:g.startValue,startDate:/^\d{4}-\d{2}-\d{2}$/.test(g.startDate)?g.startDate:C.today(),due:/^\d{4}-\d{2}-\d{2}$/.test(g.due||'')?g.due:''}}
function blank(){return {version:5,measurements:[],prefs:cleanPrefs(),goal:null,logs:{},focusPlans:{},reportPlan:null}}
let storageAvailable=true;
function loadState(){let data;try{const current=localStorage.getItem(STORE);if(current){const raw=JSON.parse(current);return {version:5,measurements:C.cleanMeasurements(raw.measurements),prefs:cleanPrefs(raw.prefs),goal:cleanGoal(raw.goal),logs:cleanLogs(raw.logs),focusPlans:cleanFocusPlans(raw.focusPlans),reportPlan:cleanReportPlan(raw.reportPlan)}}const legacy=JSON.parse(localStorage.getItem(LEGACY)||'[]');data=blank();data.measurements=C.cleanMeasurements(legacy)}catch{data=blank();storageAvailable=false}return data}
let state=loadState(),demoState=null,demo=false,page=titles[location.hash.slice(1)]?location.hash.slice(1):'report';
let reportDate='',photoInputUsed=false;
let focusPart='chest',focusView='front';
let metric='weight',period='all',selectedDate='',weekOffset=0,dayIndex=(new Date().getDay()+6)%7,toastTimer,ocrWorker,photoURL,ocrBusy=false,photoSession=0,editingId='',editingDate='';
const active=()=>demo?demoState:state;
function persist(){if(demo)return true;try{localStorage.setItem(STORE,JSON.stringify(state));storageAvailable=true;return true}catch{storageAvailable=false;toast('이 브라우저에 저장하지 못했어요. 데이터 내보내기로 백업해주세요.');return false}}
function savedToast(text){toast(demo||storageAvailable?text:'변경 내용은 현재 화면에만 반영됐어요. 저장 공간을 사용할 수 없어 내보내기로 백업해주세요.')}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200)}
function currentWeek(){return monday(shifted(C.today(),weekOffset*7))}
function activeRoutine(week=currentWeek()){const a=active(),routine=recommendedRoutine();let added=0;routine.days=routine.days.map(day=>{const planned=a.focusPlans?.[shifted(week,day.index)]||[],existing=new Set(day.exercises.map(ex=>ex.id)),extra=planned.filter(item=>!existing.has(item.id)).map(item=>({...F.lookup(item.id),sets:item.sets,_focus:true,_part:item.part}));if(!extra.length)return day;added+=extra.length;return {...day,title:day.type==='recovery'?'선택 부위 집중 루틴':day.title+' + 집중 운동',type:day.type==='recovery'?'strength':day.type,duration:(day.type==='recovery'?0:day.duration)+extra.length*5,exercises:day.type==='recovery'?extra:[...day.exercises,...extra]}});if(added)routine.reason.push('직접 담은 부위별 운동을 기본 루틴에 추가했어요. 중복 동작은 한 번만 표시하며, 추가한 동작의 세트 수를 유지해요.');return routine}
function recommendedRoutine(){const plan=activeReportPlan();return plan?R.generate(plan.record,active().prefs,active().measurements).routine:C.generateRoutine(active().prefs)}
function effectivePrefs(){const plan=activeReportPlan();return plan?{...active().prefs,goal:plan.goal}:active().prefs}
function recordForDate(date){return active().measurements.find(r=>r.date===date)}
function navigate(next){if(!titles[next])return;page=next;if(location.hash!==`#${next}`)location.hash=next;render();window.scrollTo({top:0,behavior:'auto'})}
function pageHeading(title,subtitle,actions=''){return `<div class="page-heading"><div><span class="overline">MY BODY, MY ROUTINE</span><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function addButton(){return `<button class="btn primary" data-action="measurement">${icon('plus')}측정 등록</button>`}
function smallSpark(records,key){if(records.length<2)return `<svg class="sparkline" viewBox="0 0 100 30" aria-hidden="true"><path d="M2 22H98" stroke="#e0e9e4" stroke-dasharray="3 4"/></svg>`;const vals=[...records].reverse().slice(-12).map(r=>r[key]),min=Math.min(...vals),span=Math.max(...vals)-min||1;const points=vals.map((v,i)=>`${3+i*94/(vals.length-1)},${25-(v-min)*20/span}`).join(' ');return `<svg class="sparkline" viewBox="0 0 100 30" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${metricMeta[key].color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function deltaText(delta,key){if(delta==null)return '비교 기록 없음';return `직전 대비 ${delta>0?'+':''}${fmt(delta)} ${key==='fat'?'%p':'kg'}`}
function metricCards(){const {latest,delta}=C.latestComparison(active().measurements);return `<div class="metric-grid">${Object.entries(metricMeta).map(([key,m],i)=>`<button class="metric-card ${metric===key?'selected':''}" data-action="metric" data-metric="${key}" aria-pressed="${metric===key}"><span class="metric-top">${m.name}<span class="metric-icon ${i===1?'blue':i===2?'orange':''}">${icon(m.icon)}</span></span><span class="metric-value">${fmt(latest?.[key])}<small>${m.unit}</small></span><span class="metric-foot"><span class="delta">${deltaText(delta?.[key],key)}</span>${smallSpark(active().measurements,key)}</span><span class="metric-date">${latest?`${longDate(latest.date)} 측정`:'측정값을 등록해주세요'}</span></button>`).join('')}</div>`}
function filteredRecords(){let arr=[...active().measurements].reverse();if(period!=='all'){const cutoff=shifted(C.today(),-Number(period));arr=arr.filter(r=>r.date>=cutoff)}return arr}
function chartMarkup(){const data=filteredRecords(),m=metricMeta[metric];if(!data.length)return `<div class="chart-empty">${icon('chart')}<b>${active().measurements.length?'이 기간의 측정 기록이 없어요':'한 번의 기록이 변화의 시작이에요'}</b><p>${active().measurements.length?'다른 기간을 선택해보세요.':'측정값을 등록하면 나의 그래프가 그려집니다.'}</p></div>`;const w=600,h=238,l=13,r=48,t=22,b=31,values=data.map(x=>x[metric]);let min=Math.min(...values),max=Math.max(...values);const pad=Math.max((max-min)*.3,metric==='fat'?1:.7);min=Math.max(0,min-pad);max+=pad;const start=dateObj(data[0].date).getTime(),end=dateObj(data.at(-1).date).getTime();const x=i=>data.length===1?(w-r+l)/2:l+(dateObj(data[i].date).getTime()-start)/(end-start)*(w-l-r),y=v=>t+(max-v)/(max-min)*(h-t-b);const line=data.map((r,i)=>`${x(i).toFixed(2)},${y(r[metric]).toFixed(2)}`).join(' ');let chosen=data.find(x=>x.date===selectedDate)||data.at(-1);const ci=data.indexOf(chosen);return `<svg class="trend-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${m.name} 변화 그래프, ${data.length}개 기록. 최신 ${fmt(data.at(-1)[metric])}${m.unit}"><defs><linearGradient id="chartFade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${m.color}" stop-opacity=".1"/><stop offset="1" stop-color="${m.color}" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3,py=y(v);return `<path d="M${l} ${py}H${w-r}" stroke="#edf1f3" stroke-dasharray="3 4"/><text x="${w-r+10}" y="${py+3}" class="chart-axis">${fmt(v)}</text>`}).join('')}<text x="${w-r+10}" y="11" class="chart-unit">${m.unit}</text><polygon points="${x(0)},${h-b} ${line} ${x(data.length-1)},${h-b}" fill="url(#chartFade)"/><polyline points="${line}" fill="none" stroke="${m.color}" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round"/><path d="M${x(ci)} ${t}V${h-b}" stroke="${m.color}" stroke-opacity=".22" stroke-dasharray="3 4"/>${data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d[metric])}" r="${d.date===chosen.date?5:3}" fill="${d.date===chosen.date?m.color:'white'}" stroke="${m.color}" stroke-width="1.6"><title>${longDate(d.date)} · ${fmt(d[metric])} ${m.unit}</title></circle>`).join('')}${data.map((d,i)=>i===0||i===data.length-1||i===Math.floor(data.length/2)?`<text x="${x(i)}" y="${h-7}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}" class="chart-axis">${shortDate(d.date)}</text>`:'').join('')}</svg><div class="chart-selected"><span>${longDate(chosen.date)} 선택한 기록</span><b>${m.name} ${fmt(chosen[metric])} ${m.unit}</b></div><div class="chart-points" aria-label="그래프 측정일 선택">${data.slice(-8).map(d=>`<button class="point-chip ${d.date===chosen.date?'selected':''}" data-action="chart-date" data-date="${d.date}" aria-pressed="${d.date===chosen.date}">${shortDate(d.date)}</button>`).join('')}</div>`}
function chartPanel(){return `<section class="panel chart-panel"><div class="panel-head"><div><h2>체성분 변화</h2><p>하나의 숫자보다, 쌓여가는 흐름을 보세요.</p></div>${icon('chart')}</div><div class="chart-controls"><div class="segmented" aria-label="변화 지표">${Object.entries(metricMeta).map(([k,v])=>`<button data-action="metric" data-metric="${k}" class="${metric===k?'active':''}" aria-pressed="${metric===k}">${v.name}</button>`).join('')}</div><select class="period-select" id="period" aria-label="그래프 조회 기간"><option value="all" ${period==='all'?'selected':''}>전체 기간</option><option value="90" ${period==='90'?'selected':''}>최근 3개월</option><option value="30" ${period==='30'?'selected':''}>최근 1개월</option></select></div><div class="chart-area">${chartMarkup()}</div><p class="chart-note">측정 시간·식사·수분 상태가 비슷한 조건에서 비교해주세요. 변화량은 진단이 아닙니다.</p></section>`}
function goalPanel(){const g=active().goal,latest=active().measurements[0];if(!g||!latest)return `<section class="panel goal-panel"><div class="panel-head"><h2>나의 체성분 목표</h2><button class="icon-button" data-action="goal" aria-label="목표 설정">${icon('plus')}</button></div><p class="goal-empty"><strong>방향이 생기면,<br>변화가 보이니까.</strong>나만의 목표 수치를 설정하고<br>기록이 쌓이는 과정을 확인해보세요.</p><button class="btn soft full" data-action="goal">목표 설정하기 ${icon('arrow')}</button><p class="goal-footer">내가 직접 설정하는 목표 · 언제든 수정 가능</p></section>`;const m=metricMeta[g.metric],span=g.target-g.startValue,progress=span===0?(latest[g.metric]===g.target?100:0):Math.max(0,Math.min(100,(latest[g.metric]-g.startValue)/span*100));return `<section class="panel goal-panel"><div class="panel-head"><h2>${m.name} 목표</h2><button class="icon-button" data-action="goal" aria-label="목표 수정">${icon('edit')}</button></div><span class="badge">내가 설정한 목표</span><div class="goal-title">${fmt(g.target)}<small>${m.unit}</small></div><div class="goal-sub"><span>현재 ${fmt(latest[g.metric])} ${m.unit}</span><span>${Math.round(progress)}%</span></div><div class="progress-track" role="progressbar" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100" aria-label="${m.name} 목표 진행률"><span style="width:${progress}%"></span></div><div class="goal-sub"><span>시작 ${fmt(g.startValue)} ${m.unit}</span><span>${g.due?`${longDate(g.due)}까지`:'기한 없이 나의 페이스로'}</span></div><p class="goal-footer">${longDate(g.startDate)} 기준 · 목표 수치는 권장 기준이 아닙니다.</p></section>`}
function todayPanel(){const routine=activeRoutine(monday(C.today())),todayIdx=(new Date().getDay()+6)%7,d=routine.days[todayIdx],log=active().logs[C.today()]||{},done=d.exercises.filter(e=>log[e.id]?.done).length;return `<section class="panel today-panel"><div class="panel-head"><h2>오늘의 움직임</h2><span class="badge neutral">${['월','화','수','목','금','토','일'][todayIdx]}요일</span></div><span class="today-label">TODAY'S ROUTINE</span><h3 class="today-workout-title">${active().prefs.pain?'운동 가능 범위 확인하기':d.title}</h3><p class="today-meta">${active().prefs.pain?'운동 조건에서 선택한 몸 상태를 먼저 확인해주세요.':`${d.duration}분 · ${d.exercises.length}개 동작 · ${active().prefs.place==='gym'?'헬스장':'홈트레이닝'}`}</p><div class="today-progress"><span>완료한 동작</span><b>${done} / ${d.exercises.length}</b></div><button class="btn dark full" data-action="nav" data-page="workout">${done?'기록 이어가기':'오늘 루틴 보기'} ${icon('arrow')}</button></section>`}
function comparisonPanel(){const {latest,previous,delta}=C.latestComparison(active().measurements);return `<section class="panel panel-pad"><div class="panel-head"><div><h2>지난 측정과 비교</h2><p>${previous?`${longDate(previous.date)} → ${longDate(latest.date)}`:'두 번의 측정부터 비교할 수 있어요.'}</p></div><button class="btn ghost small" data-action="nav" data-page="history">전체 기록 ${icon('right')}</button></div><div class="comparison-list">${Object.entries(metricMeta).map(([k,m])=>`<div class="comparison-row"><span>${m.name}</span><div><small>${previous?`${fmt(previous[k])} → ${fmt(latest[k])} ${m.unit}`:'이전 기록 없음'}</small><b>${delta?`${delta[k]>0?'+':''}${fmt(delta[k])} ${k==='fat'?'%p':m.unit}`:'—'}</b></div></div>`).join('')}</div></section>`}
function dashboard(){const empty=!active().measurements.length;return pageHeading('내 몸의 변화를, 한눈에.','기록은 담백하게, 변화는 선명하게.',`<button class="btn" data-action="demo">${icon('chart')}샘플 체험</button>${addButton()}`)+(empty?`<section class="empty-state"><div><h2>나의 첫 번째 기록부터 시작해요.</h2><p>측정값을 등록하면 체성분 변화와 목표를 함께 볼 수 있어요.</p><button class="btn primary" data-action="measurement">첫 측정 등록 ${icon('plus')}</button></div><div class="empty-graphic" aria-hidden="true"><span></span><span></span><span></span></div></section>`:'')+metricCards()+`<div class="dashboard-grid">${chartPanel()}<div class="right-stack">${goalPanel()}${todayPanel()}</div></div><div class="dashboard-bottom">${comparisonPanel()}<aside class="panel info-panel"><div class="info-icon">${icon('info')}</div><div><h3>수치를 이해하는 작은 기준</h3><p>골격근량은 근력과 같은 뜻이 아니에요. 측정값의 변화와 실제 운동할 때의 느낌을 함께 기록해보세요.</p><button class="btn ghost small" data-action="nav" data-page="composition">체성분 자세히 보기 ${icon('up')}</button></div></aside></div>`}
function composition(){const records=active().measurements,rec=recordForDate(selectedDate)||records[0];let content=pageHeading('나의 체성분을 이해하는 시간.','측정한 수치와 계산한 참고값을 구분해서 확인해요.',addButton());if(!rec)return content+`<section class="panel history-empty">${icon('body')}<h3>아직 측정 기록이 없어요.</h3><p>사진이나 직접 입력으로 나의 첫 기록을 등록해주세요.</p><button class="btn primary" data-action="measurement">측정 등록</button></section>`;const calc=C.computed(rec),details=[['체중',rec.weight,'kg','측정값'],['골격근량',rec.muscle,'kg','측정값'],['체지방률',rec.fat,'%','측정값'],['체지방량',calc.fatMass,'kg','체중 × 체지방률'],['제지방량',calc.leanMass,'kg','체중 − 체지방량'],['BMI',calc.bmi,'','체중 ÷ 키(m)²']];return content+`<div class="detail-date"><label for="detailDate">측정일</label><select id="detailDate">${records.map(r=>`<option value="${r.date}" ${r.date===rec.date?'selected':''}>${longDate(r.date)}</option>`).join('')}</select><button class="btn ghost small" data-action="edit-measurement" data-date="${rec.date}">${icon('edit')}수정</button></div><div class="detail-top"><section class="panel panel-pad"><div class="panel-head"><div><h2>측정 결과</h2><p>${rec.height?`키 ${fmt(rec.height,0)}cm`:'키 미등록'} · ${rec.age?`${rec.age}세`:'나이 미등록'}</p></div><span class="badge neutral">${longDate(rec.date)}</span></div><div class="detail-metrics">${details.map(([name,value,unit,note])=>`<div class="detail-value"><span>${name}</span><strong>${fmt(value)}<small>${unit}</small></strong><p>${note}${name==='BMI'&&value===null?' · 키를 등록하면 계산됩니다':''}</p></div>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-head"><div><h2>체중의 구성</h2><p>입력값으로 계산한 참고 정보</p></div>${icon('body')}</div><div class="composition-visual"><div class="donut"><svg viewBox="0 0 120 120" aria-label="체중 중 체지방 ${fmt(rec.fat)}%, 제지방 ${fmt(100-rec.fat)}%" role="img"><circle cx="60" cy="60" r="48" fill="none" stroke="#e7f0ea" stroke-width="12"/><circle cx="60" cy="60" r="48" fill="none" stroke="#91bda5" stroke-width="12"/><circle cx="60" cy="60" r="48" fill="none" stroke="#d9a575" stroke-width="12" stroke-dasharray="${301.59*rec.fat/100} 301.59" stroke-linecap="round"/></svg><div class="donut-center"><span>체중</span><b>${fmt(rec.weight)}</b><small>kg</small></div></div><div class="composition-legend"><div><span class="legend-dot"></span><span>제지방량</span><b>${fmt(calc.leanMass)} kg</b></div><div><span class="legend-dot fat"></span><span>체지방량</span><b>${fmt(calc.fatMass)} kg</b></div></div></div><p class="chart-note">제지방량에는 근육 외에 수분·뼈·장기 등이 포함됩니다. 순수 근육량으로 해석하지 않습니다.</p></section></div><div class="explain-grid">${[['scale','체중만으로 다 알 수 없어요','체중이 같아도 골격근량과 체지방률의 변화는 다를 수 있어요. 세 수치의 흐름을 함께 확인하세요.'],['muscle','골격근량과 근력은 달라요','측정한 골격근량은 추세를 보는 정보예요. 실제 힘과 운동 수행 능력은 수행 기록과 함께 확인하세요.'],['drop','한 번의 변화보다 추세를','식사·수분·운동·측정 시간에 따라 수치가 달라질 수 있어요. 같은 조건에서 여러 번의 기록을 비교하세요.']].map(([ic,title,copy])=>`<section class="panel explain-card"><h3>${icon(ic)}${title}</h3><p>${copy}</p></section>`).join('')}</div>`}
function workout(){const routine=activeRoutine(),week=currentWeek(),day=routine.days[dayIndex],date=shifted(week,dayIndex),logs=active().logs[date]||{},count=day.exercises.filter(e=>logs[e.id]?.done).length;const trained=Array.from({length:7},(_,i)=>active().logs[shifted(week,i)]).filter(log=>log&&Object.values(log).some(x=>x.done)).length;return pageHeading('나에게 맞는 움직임의 리듬.','운동 조건에 맞춰 만들고, 실제로 한 만큼 기록하세요.',`<button class="btn" data-action="preferences">${icon('settings')}운동 조건</button><button class="btn" data-action="print">${icon('file')}인쇄</button>`)+reportRoutineBanner()+`<div class="toolbar"><div class="week-label"><button class="icon-button" data-action="week-prev" aria-label="이전 주">${icon('left')}</button><span>${longDate(week)} — ${shortDate(shifted(week,6))}</span><button class="icon-button" data-action="week-next" aria-label="다음 주">${icon('right')}</button></div><button class="btn ghost small" data-action="week-today">이번 주로</button></div><div class="week-days" aria-label="주간 운동 날짜">${routine.days.map((d,i)=>{const dt=shifted(week,i),done=Object.values(active().logs[dt]||{}).some(x=>x.done);return `<button class="week-day ${i===dayIndex?'selected':''} ${dt===C.today()?'today':''}" data-action="day" data-index="${i}" aria-pressed="${i===dayIndex}"><span>${d.weekday}</span><b>${dt.slice(8)}</b><small>${d.type==='strength'?'근력':d.type==='cardio'?'유산소':'회복'}</small><span class="day-dot ${done?'done':''}"></span></button>`}).join('')}</div><div class="workout-layout"><section class="panel panel-pad"><div class="workout-title"><div><h2>${day.title}</h2><p>${longDate(date)} · ${day.duration}분 · ${day.exercises.length}개 동작</p></div><span class="badge">${count}/${day.exercises.length} 완료</span></div>${active().prefs.pain?`<div class="recovery-panel">${icon('shield')}<h3>가능한 움직임부터 확인해요.</h3><p>운동 조건에 통증·부상·임신 또는 질환이 선택되어 있어요. 현재 상태에 맞는 운동 종류와 강도를 전문가와 확인한 뒤 조건을 수정해주세요.</p><button class="btn soft" data-action="preferences">운동 조건 확인</button></div>`:`${day.type==='recovery'?`<div class="recovery-panel">${icon('leaf')}<h3>회복도 루틴의 일부예요.</h3><p>오늘은 가벼운 움직임을 선택하거나 충분히 쉬어가세요.</p></div>`:''}<div class="exercise-list ${day.type==='recovery'?'section-gap':''}">${day.exercises.map((ex,i)=>{const log=logs[ex.id];return `<article class="exercise-row"><span class="exercise-no">${String(i+1).padStart(2,'0')}</span><div class="exercise-content"><h3>${ex.name}</h3><p>${F.exerciseKind(ex.id)==='strength'?`${ex.sets}세트 × ${ex.reps}`:ex.reps}${ex._focus?'<span class="focus-badge">직접 담은 운동</span>':''}${ex._analysis?'<span class="focus-badge">분석 우선 동작</span>':''}${log?.done?`<br><span style="color:#6e9d86">기록됨${log.sets?` · ${log.sets}세트`:''}${log.reps?` × ${log.reps}회`:''}${log.weight!==null&&log.weight!==undefined?` · ${fmt(log.weight)}kg`:''}${log.minutes?` · ${log.minutes}분`:''}</span>`:''}</p><button class="exercise-guide" data-action="guide" data-exercise="${ex.id}">동작 설명 보기 ↗</button>${ex._focus?`<button class="focus-remove-plan" data-action="focus-remove" data-exercise="${ex.id}" data-date="${date}">집중 루틴에서 빼기</button>`:''}</div><div class="exercise-actions"><button class="btn small" data-action="log" data-exercise="${ex.id}">기록</button><button class="complete-toggle ${log?.done?'done':''}" data-action="complete" data-exercise="${ex.id}" aria-label="${ex.name} ${log?.done?'완료 취소':'완료 표시'}" aria-pressed="${!!log?.done}">${icon('check')}</button></div></article>`}).join('')}</div>`}${pastLogsSection(date,logs,day.exercises)}<div class="weekly-tally"><span>이번 주 활동을 기록한 날</span><b>${trained}일</b></div></section><div><section class="panel panel-pad"><div class="panel-head"><div><h2>이렇게 구성했어요</h2><p>내가 선택한 조건과 추천 근거</p></div>${icon('target')}</div><span class="badge">${routine.title}</span><ul class="routine-reasons">${routine.reason.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><button class="btn soft full section-gap" data-action="preferences">나의 운동 조건 조정</button></section><aside class="panel info-panel section-gap"><div class="info-icon">${icon('info')}</div><div><h3>기록은 실제 수행한 만큼</h3><p>체성분 수치로 근력이나 수행 능력을 단정하지 않아요. 완료한 동작과 실제 중량·횟수를 남기고 내 페이스를 확인하세요.</p></div></aside></div></div>`}

function pastLogsSection(date,logs,scheduled){const extra=Object.entries(logs).filter(([id,log])=>log.done&&!scheduled.some(e=>e.id===id));if(!extra.length)return '';return `<div class="section-gap"><h3 style="font-size:13px;color:#718b80">이 날짜에 기록한 다른 동작</h3><p class="chart-note">운동 조건을 바꾸기 전에 남긴 기록도 유지됩니다.</p><div class="exercise-list section-gap">${extra.map(([id,log])=>{const ex=exerciseById(id);return `<article class="exercise-row"><span class="exercise-no">✓</span><div class="exercise-content"><h3>${esc(ex.name)}</h3><p>${log.sets?`${log.sets}세트`:''}${log.reps?` × ${log.reps}회`:''}${log.weight!==null?` · ${fmt(log.weight)}kg`:''}${log.minutes?`${log.minutes}분`:''}${!log.sets&&!log.minutes?'완료 기록':''}</p><button class="exercise-guide" data-action="guide" data-exercise="${id}">동작 설명 보기 ↗</button></div><div class="exercise-actions"><button class="btn small" data-action="log" data-exercise="${id}">수정</button><button class="complete-toggle done" data-action="complete" data-exercise="${id}" aria-label="${esc(ex.name)} 완료 취소">${icon('check')}</button></div></article>`}).join('')}</div></div>`}

function historyView(){const records=active().measurements;return pageHeading('변화를 쌓아온 나의 기록.','날짜별 측정값을 확인하고, 수정하고, 비교하세요.',`<button class="btn" data-action="export">${icon('down')}내보내기</button>${addButton()}`)+`<div class="toolbar"><span class="badge neutral">측정 기록 ${records.length}개 · 날짜별 1개</span><button class="btn ghost small" data-action="import">${icon('upload')}백업 가져오기</button></div><section class="panel">${records.length?`<div class="table-wrap"><table class="records-table"><thead><tr><th scope="col">측정일</th><th scope="col">체중</th><th scope="col">골격근량</th><th scope="col">체지방률</th><th scope="col">체지방량</th><th scope="col">관리</th></tr></thead><tbody>${records.map(r=>`<tr><td>${longDate(r.date)}</td><td>${fmt(r.weight)} kg</td><td>${fmt(r.muscle)} kg</td><td>${fmt(r.fat)} %</td><td>${fmt(C.computed(r).fatMass)} kg</td><td><div class="table-actions"><button data-action="detail" data-date="${r.date}">상세</button><button data-action="edit-measurement" data-date="${r.date}">수정</button><button data-action="delete-measurement" data-date="${r.date}">삭제</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="history-empty">${icon('history')}<h3>오늘부터 기록을 쌓아보세요.</h3><p>측정값을 저장하면 날짜별 변화가 여기에 모입니다.</p><button class="btn primary" data-action="measurement">첫 측정 등록</button></div>`}</section><p class="data-note">${demo?'샘플 체험 기록입니다. 실제 기록에는 저장되지 않아요.':'기록은 이 브라우저에 저장됩니다. 브라우저 데이터를 지우거나 다른 기기로 이동하기 전 내보내기로 백업해주세요.'}</p>`}
function settingsView(){const p=active().prefs;return pageHeading('나에게 맞게, 편안하게.','운동 조건과 기록 데이터를 관리하세요.')+`<div class="settings-grid"><section class="panel panel-pad"><div class="panel-head"><h2>나의 운동 조건</h2><button class="btn ghost small" data-action="preferences">수정 ${icon('edit')}</button></div>${[['목표',{balance:'체력 향상 · 균형',loss:'체지방 감량',gain:'근육 증가'}[p.goal]],['운동 경험',p.level==='regular'?'규칙적으로 운동 중':'처음이거나 오랜만'],['운동 일정',`주 ${p.days}일 · 1회 ${p.minutes}분`],['운동 장소 · 기구',p.place==='gym'?'헬스장 · 기구 사용':p.equipment==='band'?'집 · 운동 밴드':'집 · 맨몸']].map(([k,v])=>`<div class="settings-row"><span>${k}</span><b>${v}</b></div>`).join('')}</section><section class="panel panel-pad"><div class="panel-head"><h2>기록 데이터</h2>${icon('shield')}</div><p class="settings-copy">${demo?'지금은 샘플 체험 중입니다. 변경한 내용은 실제 기록에 반영되지 않습니다.':storageAvailable?'이 브라우저에 측정값·목표·운동 기록을 저장합니다. 계정이나 다른 기기로 자동 동기화되지는 않습니다.':'브라우저 저장 공간을 사용할 수 없습니다. 현재 기록을 내보내기로 백업해주세요.'}</p><div class="heading-actions" style="justify-content:start;flex-direction:row"><button class="btn" data-action="export">${icon('down')}백업 내보내기</button><button class="btn" data-action="import">${icon('upload')}가져오기</button></div><p class="data-note">사진은 저장하지 않고 브라우저에서 인식합니다. 내보낸 파일에는 나의 측정값과 운동 기록이 포함됩니다.</p></section><section class="panel panel-pad"><div class="panel-head"><h2>체성분을 이해하는 자료</h2>${icon('file')}</div><p class="settings-copy">측정값의 의미와 기능 구성을 이해할 때 참고한 공식 자료입니다.</p><div class="settings-links"><a href="https://www.inbody.co.jp/application-topic/" target="_blank" rel="noopener">InBody 공식 앱 기능 가이드 ↗</a><a href="https://inbodyusa.com/inbody-app/" target="_blank" rel="noopener">InBody 공식 앱 소개 ↗</a><a href="https://www.mea.inbody.com/learn/Result.php" target="_blank" rel="noopener">InBody 결과지 지표 설명 ↗</a></div></section><section class="panel panel-pad"><div class="panel-head"><h2>바디루틴에 대하여</h2><span class="badge">WEB APP</span></div><p class="settings-copy">확인한 인바디 수치와 운동 조건을 연결하는 독립적인 기록·추천 도구입니다. 인바디 계정·기기와 직접 연결되지 않으며, 표준 범위·의학적 진단·독자적인 인바디 점수를 생성하지 않습니다.</p><button class="btn soft" data-action="demo">${icon('chart')}샘플 데이터로 전체 기능 체험</button></section></div>`}
function render(){const nav=[['report','file'],['focus','body'],['dashboard','dashboard'],['composition','body'],['workout','workout'],['history','history'],['settings','settings']];$('navigation').innerHTML=nav.map(([key,ic])=>`<a class="side-nav-item ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(ic)}${titles[key]}</a>`).join('');$('bottomNavigation').innerHTML=nav.filter(([key])=>!['composition','history'].includes(key)).map(([key,ic])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ic)}${key==='report'?'분석':key==='focus'?'포커스':key==='workout'?'운동':key==='history'?'기록':key==='settings'?'설정':'홈'}</a>`).join('');$('breadcrumb').innerHTML=`내 건강 공간 <span>/</span> ${titles[page]}`;$('todayLabel').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short'}).format(new Date());$('demoBanner').hidden=!demo;const views={report:reportPage,focus:focusPage,dashboard,composition,workout,history:historyView,settings:settingsView};$('content').innerHTML=views[page]();const drop=$('reportDrop');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();const file=e.dataTransfer.files[0];measurementDialog();processPhoto(file)}}document.title=`${titles[page]} · 바디루틴`}
function openDialog(title,subtitle,body){photoSession++;$('dialogContent').innerHTML=`<div class="dialog-head"><div><h2 id="dialogTitle">${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close-dialog" aria-label="닫기">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('appDialog').open)$('appDialog').showModal()}
function closeDialog(){photoSession++;ocrBusy=false;if(photoURL){URL.revokeObjectURL(photoURL);photoURL=null}$('appDialog').close();$('dialogContent').innerHTML=''}
function field(id,label,value='',unit='',attrs=''){return `<label class="field" for="${id}">${label}${unit?`<div class="unit-input"><input id="${id}" name="${id}" type="number" value="${esc(value)}" ${attrs}><span>${unit}</span></div>`:`<input id="${id}" name="${id}" value="${esc(value)}" ${attrs}>`}<span class="field-error" id="${id}Error"></span></label>`}
function measurementDialog(date,choosePhoto=false){const existing=date?recordForDate(date):null,last=active().measurements[0];editingId=existing?.id||'';editingDate=existing?.date||'';photoInputUsed=false;openDialog(choosePhoto?'인바디 사진 분석':existing?'측정 기록과 분석 정보 수정':'새 측정 등록','사진 읽기, 수치 확인, 분석 근거 확인 후 루틴에 적용합니다.',`<form id="measurementForm" novalidate><label class="upload-box" id="drop"><input id="photo" type="file" accept="image/jpeg,image/png,image/webp" hidden><span>${icon('upload')}<span><b>인바디 결과지 사진으로 입력</b><small>JPG · PNG · WEBP, 최대 10MB / 사진은 저장하지 않아요</small></span></span><span class="btn small">사진 선택</span></label><img id="photoPreview" class="photo-preview" alt="등록한 인바디 결과지" hidden><p id="ocrStatus" class="ocr-message" role="status" hidden></p><div id="ocrResultSummary" class="ocr-result-summary" hidden></div><div id="measurementError" class="error-summary" role="alert"></div><div class="form-grid">${field('mdate','측정일',existing?.date||C.today(),'','type="date" required max="'+C.today()+'"')}${field('height','키',existing?.height??last?.height??'','cm','min="100" max="230" step="0.1" placeholder="170" required')}${field('age','나이',existing?.age??last?.age??'','세','min="18" max="64" step="1" placeholder="28" required')}${field('weight','체중',existing?.weight??'','kg','min="30" max="250" step="0.1" placeholder="65.0" required')}${field('muscle','골격근량',existing?.muscle??'','kg','min="5" max="100" step="0.1" placeholder="27.0" required')}${field('fat','체지방률',existing?.fat??'','%','min="3" max="65" step="0.1" placeholder="24.0" required')}</div>${reportExtraFields(existing?.report)}<label id="ocrReview" class="ocr-review" hidden><input id="ocrReviewed" type="checkbox"> 사진의 측정일과 모든 숫자·부호를 원본과 대조해 확인했어요.</label><div class="dialog-note">같은 날짜의 측정값은 1개만 보관합니다. 없는 결과지 항목은 비워두세요. 분석의 근거가 부족하면 운동 방향을 임의로 결정하지 않습니다.${demo?'<br>샘플 체험 모드: 실제 기록에는 반영되지 않습니다.':''}</div><div class="dialog-actions"><button type="button" class="btn" data-action="close-dialog">취소</button><button class="btn primary" id="saveMeasurement">저장하고 분석 확인</button></div></form>`);$('drop').tabIndex=0;$('drop').setAttribute('role','button');$('drop').setAttribute('aria-label','인바디 결과지 사진 선택');$('drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('photo').click()}};$('photo').onchange=e=>processPhoto(e.target.files[0]);$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('drag')};$('drop').ondragleave=()=>$('drop').classList.remove('drag');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('drag');processPhoto(e.dataTransfer.files[0])};if(choosePhoto)$('photo').click()}
function goalDialog(){const latest=active().measurements[0];if(!latest){toast('먼저 측정값을 등록하면 목표를 설정할 수 있어요.');return}const g=active().goal;openDialog('나의 체성분 목표','현재 측정값을 시작점으로 나만의 목표를 설정해요.',`<form id="goalForm"><div id="goalError" class="error-summary" role="alert"></div><div class="form-grid"><label class="field">목표 지표<select id="goalMetric">${Object.entries(metricMeta).map(([k,v])=>`<option value="${k}" ${g?.metric===k?'selected':''}>${v.name} (${v.unit})</option>`).join('')}</select></label>${field('goalTarget','목표 수치',g?.target??'','','type="number" step="0.1" required placeholder="직접 설정"')}${field('goalDue','목표 날짜 (선택)',g?.due||'','','type="date" min="'+C.today()+'"')}</div><div class="dialog-note">내가 직접 정한 목표이며 권장 수치를 제안하는 기능은 아닙니다. 저장 시 최신 측정값을 새 시작점으로 사용합니다.</div><div class="dialog-actions">${g?'<button type="button" class="btn ghost" data-action="remove-goal">목표 해제</button>':''}<button type="button" class="btn" data-action="close-dialog">취소</button><button class="btn primary">목표 저장</button></div></form>`)}
function selectField(id,label,options,current){return `<label class="field">${label}<select id="${id}">${options.map(([v,name])=>`<option value="${v}" ${String(v)===String(current)?'selected':''}>${name}</option>`).join('')}</select></label>`}
function preferencesDialog(){const p=active().prefs;openDialog('나에게 맞는 운동 조건','실제로 꾸준히 할 수 있는 조건을 선택해주세요.',`<form id="prefsForm">${activeReportPlan()?`<p class="report-photo-note">현재 인바디 분석 ‘${esc(activeReportPlan().title)}’을 적용 중입니다. 아래 수동 목표를 바꾸면 분석 적용을 해제합니다. 장소·시간 등 다른 조건만 바꾸면 분석 적용을 유지합니다.</p>`:''}<div class="form-grid">${selectField('pgoal','운동 목표',[['balance','체력 향상 · 균형'],['loss','체지방 감량'],['gain','근육 증가']],p.goal)}${selectField('plevel','운동 경험',[['beginner','처음이거나 오랜만'],['regular','규칙적으로 운동 중']],p.level)}${selectField('pdays','주당 운동 일수',[[2,'주 2일'],[3,'주 3일'],[4,'주 4일'],[5,'주 5일']],p.days)}${selectField('pminutes','한 번의 운동 시간',[[20,'20분'],[40,'40분'],[60,'60분']],p.minutes)}${selectField('pplace','운동 장소',[['home','집 · 홈트레이닝'],['gym','헬스장']],p.place)}${selectField('pequipment','집에서 사용할 기구',[['none','기구 없이 맨몸'],['band','운동 밴드']],p.equipment)}</div><label class="check-field"><input id="ppain" type="checkbox" ${p.pain?'checked':''}>통증·부상, 임신 또는 운동에 영향을 주는 질환이 있어요.</label><div class="dialog-note">인바디 분석 적용 여부와 운동 목표·경험·시간·일수·장소·기구를 운동 구성에 사용해요. 수치만으로 운동 능력을 단정하거나 중량을 정하지 않습니다. 장소를 헬스장으로 선택하면 헬스장 기구 구성을 사용합니다.</div><div class="dialog-actions"><button type="button" class="btn" data-action="close-dialog">취소</button><button class="btn primary">조건 적용하기</button></div></form>`);$('pequipment').disabled=p.place==='gym';$('pplace').onchange=()=>$('pequipment').disabled=$('pplace').value==='gym'}
function exerciseById(id){return F.lookup(id)}
function guideDialog(id){const ex=exerciseById(id);if(!ex)return;openDialog(ex.name,'내 페이스에 맞춰 천천히 움직여요.',`<div class="guide-pictogram">${icon('workout')}</div><section class="guide-block"><h3>동작 방법</h3><p>${esc(ex.guide)}</p></section><section class="guide-block"><h3>확인할 점</h3><p>${esc(ex.caution)}</p></section><section class="guide-block"><h3>어려울 때는</h3><p>${esc(ex.alternative)}</p></section><div class="dialog-actions"><button class="btn primary" data-action="close-dialog">확인했어요</button></div>`)}
function logDialog(id){const date=shifted(currentWeek(),dayIndex);if(date>C.today()){toast('아직 오지 않은 날짜에는 수행 기록을 남길 수 없어요.');return}const ex=exerciseById(id);if(!ex)return;const log=active().logs[date]?.[id],scheduled=activeRoutine().days[dayIndex],type=log?.sets!=null?'strength':F.exerciseKind(id)||scheduled.type;openDialog('실제로 한 만큼 기록해요',`${longDate(date)} · ${ex.name}`,`<form id="logForm" data-exercise="${id}" data-date="${date}"><div id="logError" class="error-summary" role="alert"></div>${type==='strength'?`<div class="form-grid three">${field('logSets','수행 세트',log?.sets??'','세트','min="1" max="10" step="1" required placeholder="2"')}${field('logReps','세트당 횟수',log?.reps??'','회','min="1" max="100" step="1" required placeholder="10"')}${field('logWeight','사용 중량 (선택)',log?.weight??'','kg','min="0" max="500" step="0.1" placeholder="맨몸은 0"')}</div>`:`<div class="form-grid">${field('logMinutes','움직인 시간',log?.minutes??'','분','min="1" max="240" step="1" required placeholder="15"')}</div>`}<div class="dialog-note">저장하면 해당 동작이 완료로 표시됩니다. 중량은 직접 사용한 값이며, 빈칸은 기록하지 않습니다.</div><div class="dialog-actions"><button type="button" class="btn" data-action="close-dialog">취소</button><button class="btn primary">운동 기록 저장</button></div></form>`)}
function startDemo(){if(demo){navigate('dashboard');return}demoState=blank();demoState.measurements=C.cleanMeasurements(C.demoMeasurements());demoState.prefs=cleanPrefs({goal:'gain',days:3,place:'gym',level:'regular',minutes:40});const sorted=[...demoState.measurements].reverse();demoState.goal={metric:'muscle',target:30,startValue:sorted[0].muscle,startDate:sorted[0].date,due:shifted(C.today(),60)};demo=true;metric='weight';period='all';selectedDate='';weekOffset=0;dayIndex=(new Date().getDay()+6)%7;navigate('dashboard');toast('샘플 체험을 시작했어요. 실제 기록에는 저장되지 않습니다.')}
function exportBackup(){const blob=new Blob([JSON.stringify({...active(),version:5,exportedAt:new Date().toISOString(),sample:demo},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bodyroutine-${demo?'sample-':''}${C.today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(demo?'샘플 백업 파일을 내보냈어요.':'나의 기록을 백업 파일로 내보냈어요.')}
async function importBackup(file){if(!file)return;if(file.size>1024*1024){toast('1MB 이하의 바디루틴 백업 파일을 선택해주세요.');return}try{const raw=JSON.parse(await file.text());if(raw.sample&&!demo){toast('샘플 체험 파일은 실제 기록으로 가져올 수 없어요.');return}if(!raw||!Array.isArray(raw.measurements))throw new Error();const measurements=C.cleanMeasurements(raw.measurements),logs=cleanLogs(raw.logs),focusPlans=cleanFocusPlans(raw.focusPlans);if(!measurements.length&&!Object.keys(logs).length&&!Object.keys(focusPlans).length)throw new Error();openDialog('백업 파일 확인','기존 기록을 유지하면서 유효한 기록을 합칩니다.',`<p class="settings-copy">측정 기록 <b>${measurements.length}개</b>, 운동 기록 <b>${Object.keys(logs).length}일</b>, 집중 운동 계획 <b>${Object.keys(focusPlans).length}일</b>을 찾았어요.<br>같은 날짜의 측정값은 저장 시간이 더 최근인 값을 사용합니다. 운동 기록은 가져오는 파일의 같은 동작 기록으로 갱신합니다.</p><div class="dialog-note">운동 조건·목표·분석 적용 상태는 현재 설정을 유지합니다.${demo?'<br>샘플 체험에만 반영됩니다.':''}</div><div class="dialog-actions"><button class="btn" data-action="close-dialog">취소</button><button class="btn primary" id="confirmImport">기록 합치기</button></div>`);$('confirmImport').onclick=()=>{const a=active();a.measurements=C.cleanMeasurements([...a.measurements,...measurements]);for(const [date,entries]of Object.entries(logs))a.logs[date]={...(a.logs[date]||{}),...entries};for(const [date,entries]of Object.entries(focusPlans))a.focusPlans[date]=[...new Map([...(a.focusPlans[date]||[]),...entries].map(ex=>[ex.id,ex])).values()].slice(0,6);persist();closeDialog();render();savedToast('백업 기록을 합쳤어요.')}}catch{toast('유효한 바디루틴 JSON 백업 파일을 선택해주세요.')}}
async function getOcrWorker(){if(!ocrWorker)ocrWorker=(async()=>{if(!window.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script)});return window.Tesseract.createWorker('kor+eng')})();try{return await ocrWorker}catch(e){ocrWorker=null;throw e}}
async function processPhoto(file){
  if(!file||ocrBusy)return;
  const status=$('ocrStatus'),summary=$('ocrResultSummary');status.hidden=false;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){status.textContent='10MB 이하의 JPG, PNG, WEBP 사진을 선택해주세요.';return;}
  const session=photoSession;ocrBusy=true;photoInputUsed=true;
  $('saveMeasurement').disabled=true;$('photo').disabled=true;$('ocrReview').hidden=false;$('ocrReviewed').checked=false;
  if(summary){summary.hidden=true;summary.innerHTML='';}
  const basicIds=['mdate','height','age','weight','muscle','fat'];
  const optionalIds=['reportSex','reportMuscleControl','reportFatControl'];
  const regionKeys=['RightArm','LeftArm','Trunk','RightLeg','LeftLeg'];
  for(const id of [...basicIds,...optionalIds,...regionKeys.map(k=>'seg'+k),...regionKeys.map(k=>'rating'+k)])if($(id)){$(id).value='';$(id).style.borderColor='';$(id).removeAttribute?.('data-ocr');}
  $('segmentConfirmed').checked=false;if($('ratingConfirmed'))$('ratingConfirmed').checked=false;
  if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(file);$('photoPreview').src=photoURL;$('photoPreview').hidden=false;
  status.textContent='인식 도구를 준비하고 있어요. 처음 실행할 때는 다운로드 시간이 필요합니다.';
  try{
    const worker=await getOcrWorker();
    if(session!==photoSession)return;
    const result=await window.PhotoReader.recognize(file,worker,message=>{if(session===photoSession&&$('ocrStatus'))$('ocrStatus').textContent=message;},()=>session===photoSession);
    if(session!==photoSession)return;
    const parsed=R.parse(result.text,result.words,result.geometry);
    const fill=(id,value)=>{if($(id)&&value!==null&&value!==undefined){$(id).value=String(value);$(id).setAttribute('data-ocr','recognized');}};
    for(const[key,value]of Object.entries(parsed.values))fill(key==='date'?'mdate':key,value);
    for(const[key,id]of [['sex','reportSex'],['muscleControl','reportMuscleControl'],['fatControl','reportFatControl']])fill(id,parsed.extra[key]);
    let segmentCount=0,ratingCount=0;
    for(const[key,value]of Object.entries(parsed.extra.segments)){if(value!==null){fill('seg'+key[0].toUpperCase()+key.slice(1),value);segmentCount++;}}
    for(const[key,value]of Object.entries(parsed.extra.segmentRatings||{})){if(value!==null){fill('rating'+key[0].toUpperCase()+key.slice(1),value);ratingCount++;}}
    if(segmentCount)$('reportSegmentDetails').open=true;
    if(ratingCount)$('reportRatingDetails').open=true;
    const fields=[['mdate','측정일'],['height','키'],['age','나이'],['weight','체중'],['muscle','골격근량'],['fat','체지방률']];
    const missing=fields.filter(([id])=>!$(id).value).map(([,name])=>name),filled=fields.length-missing.length;
    for(const[id]of fields)if(!$(id).value)$(id).setAttribute('data-ocr','missing');
    const total=parsed.matched.length+parsed.extraMatched.length;
    status.textContent=total?`사진에서 ${total}개 항목을 자동 입력했어요. 원본과 대조한 뒤 확인하고 저장해주세요.`:'확실하게 읽은 항목이 없어요. 결과지가 정면으로 나온 선명한 사진을 선택하거나 직접 입력해주세요.';
    if(summary){summary.hidden=false;summary.innerHTML=`<strong>기본 정보 ${filled} / ${fields.length} 자동 입력</strong><p>${missing.length?`확인이 필요한 항목: ${missing.map(esc).join(' · ')}. 빈칸만 직접 채워주세요.`:'측정일과 기본 수치가 채워졌어요. 숫자·소수점·부호를 확인해주세요.'}</p>${ratingCount?`<p>부위별 평가 ${ratingCount}개를 읽었어요. 아래 평가 문구도 확인해주세요.</p>`:''}${parsed.warnings.length?`<details><summary>인식 결과에서 확인할 내용</summary><ul>${parsed.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:''}`;}
  }catch{
    if(session!==photoSession)return;
    status.textContent='사진 인식을 완료하지 못했어요. 인터넷 연결을 확인하고 다시 선택하거나 사진을 보면서 직접 입력해주세요.';
  }finally{if(session===photoSession){ocrBusy=false;$('saveMeasurement').disabled=false;$('photo').disabled=false;}}
}

document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;switch(action){case'report-photo':measurementDialog(undefined,true);break;case'apply-report':applyReportPlan();break;case'clear-report':active().reportPlan=null;persist();render();savedToast('분석 적용을 해제하고 직접 선택한 운동 조건으로 돌아왔어요.');break;case'report-focus':if(Object.hasOwn(F.parts,button.dataset.part)){focusPart=button.dataset.part;focusView=F.parts[focusPart].view;navigate('focus')}break;case'focus-part':if(Object.hasOwn(F.parts,button.dataset.part)){focusPart=button.dataset.part;if(['back','glutes'].includes(focusPart))focusView='back';else if(['chest','core'].includes(focusPart))focusView='front';render()}break;case'focus-view':focusView=button.dataset.view==='back'?'back':'front';if(!['shoulders','arms','legs'].includes(focusPart)&&F.parts[focusPart].view!==focusView){focusPart=focusView==='back'?'back':'chest'}render();break;case'focus-add':addFocusExercise(button.dataset.exercise,button.dataset.part);break;case'focus-remove':removeFocusExercise(button.dataset.exercise,button.dataset.date||C.today());break;case'focus-today':weekOffset=0;dayIndex=(new Date().getDay()+6)%7;navigate('workout');break;case'nav':navigate(button.dataset.page);break;case'measurement':measurementDialog();break;case'edit-measurement':measurementDialog(button.dataset.date);break;case'detail':selectedDate=button.dataset.date;navigate('composition');break;case'metric':metric=button.dataset.metric;render();break;case'chart-date':selectedDate=button.dataset.date;render();break;case'demo':startDemo();break;case'exit-demo':demo=false;demoState=null;selectedDate='';render();toast('나의 실제 기록으로 돌아왔어요.');break;case'goal':goalDialog();break;case'remove-goal':active().goal=null;persist();closeDialog();render();savedToast('목표를 해제했어요.');break;case'preferences':preferencesDialog();break;case'close-dialog':closeDialog();break;case'week-prev':weekOffset--;render();break;case'week-next':weekOffset++;render();break;case'week-today':weekOffset=0;dayIndex=(new Date().getDay()+6)%7;render();break;case'day':dayIndex=Number(button.dataset.index);render();break;case'guide':guideDialog(button.dataset.exercise);break;case'log':logDialog(button.dataset.exercise);break;case'complete':{const date=shifted(currentWeek(),dayIndex);if(date>C.today()){toast('미래 날짜에는 완료 표시를 할 수 없어요.');break}const a=active(),id=button.dataset.exercise;if(!exerciseIds.has(id))break;a.logs[date]??={};const old=a.logs[date][id];a.logs[date][id]={done:!old?.done,sets:old?.sets??null,reps:old?.reps??null,weight:old?.weight??null,minutes:old?.minutes??null};persist();render();savedToast(a.logs[date][id].done?'완료한 동작으로 기록했어요.':'완료 표시를 취소했어요.');break}case'print':window.print();break;case'export':exportBackup();break;case'import':$('importFile').click();break;case'delete-measurement':{const date=button.dataset.date;openDialog('측정 기록을 삭제할까요?',`${longDate(date)} 측정값`, `<p class="settings-copy">선택한 날짜의 체성분 측정값을 삭제합니다. 운동 기록은 유지됩니다. 필요하면 먼저 내보내기로 백업해주세요.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">취소</button><button class="btn danger" id="confirmDelete">측정 기록 삭제</button></div>`);$('confirmDelete').onclick=()=>{active().measurements=active().measurements.filter(r=>r.date!==date);persist();closeDialog();render();savedToast('선택한 측정 기록을 삭제했어요.')};break}}});
document.addEventListener('change',event=>{if(event.target.id==='reportDate'){reportDate=event.target.value;render()}if(event.target.id==='period'){period=event.target.value;render()}if(event.target.id==='detailDate'){selectedDate=event.target.value;render()}});
document.addEventListener('submit',event=>{const form=event.target;if(!['measurementForm','goalForm','prefsForm','logForm'].includes(form.id))return;event.preventDefault();if(form.id==='measurementForm'){if(ocrBusy)return;const raw={date:$('mdate').value};for(const key of ['height','age','weight','muscle','fat'])raw[key]=$(key).value;if(editingId)raw.id=editingId;const reportInput=readReportForm();if(!reportInput.ok){$('measurementError').textContent=reportInput.error;return}raw.report=reportInput.report;const validation=C.validateMeasurement(raw);for(const key of ['height','age','weight','muscle','fat','mdate']){const msg=validation.errors[key==='mdate'?'date':key]||'';$(key).setAttribute('aria-invalid',msg?'true':'false');$(key+'Error').textContent=msg}if(!validation.ok){$('measurementError').textContent='입력한 숫자와 날짜를 확인해주세요.';form.querySelector('[aria-invalid=true]')?.focus();return}if(!$('ocrReview').hidden&&!$('ocrReviewed').checked){$('measurementError').textContent='사진의 수치와 모든 입력값을 대조한 뒤 확인에 체크해주세요.';$('ocrReviewed').focus();return}const a=active(),value=validation.value;a.measurements=C.cleanMeasurements([...a.measurements.filter(r=>r.date!==editingDate&&r.date!==value.date),value]);persist();selectedDate=value.date;reportDate=value.date;closeDialog();navigate('report');savedToast(demo?'샘플 체험에 결과를 추가했어요. 분석 근거를 확인해주세요.':'결과를 저장했어요. 분석 근거를 확인한 뒤 루틴에 적용해주세요.')}else if(form.id==='goalForm'){const m=$('goalMetric').value,target=Number($('goalTarget').value),due=$('goalDue').value,bounds={weight:[30,250],muscle:[5,100],fat:[3,65]}[m];if(!$('goalTarget').value||target<bounds[0]||target>bounds[1]||!Number.isFinite(target)){ $('goalError').textContent=`목표 수치를 ${bounds[0]}–${bounds[1]} 범위로 직접 입력해주세요.`;return}if(due&&due<C.today()){$('goalError').textContent='목표 날짜는 오늘 이후로 선택해주세요.';return}const latest=active().measurements[0];active().goal={metric:m,target,startValue:latest[m],startDate:latest.date,due};persist();closeDialog();render();savedToast('나의 목표를 저장했어요.')}else if(form.id==='prefsForm'){const previousGoal=active().prefs.goal;active().prefs=cleanPrefs({goal:$('pgoal').value,level:$('plevel').value,days:Number($('pdays').value),minutes:Number($('pminutes').value),place:$('pplace').value,equipment:$('pequipment').value,pain:$('ppain').checked});if(active().prefs.goal!==previousGoal)active().reportPlan=null;persist();closeDialog();render();savedToast('운동 조건에 맞춰 루틴을 조정했어요.')}else if(form.id==='logForm'){const record={done:true,sets:null,reps:null,weight:null,minutes:null};if($('logSets')){record.sets=Number($('logSets').value);record.reps=Number($('logReps').value);record.weight=$('logWeight').value===''?null:Number($('logWeight').value);if(!Number.isInteger(record.sets)||record.sets<1||record.sets>10||!Number.isInteger(record.reps)||record.reps<1||record.reps>100||record.weight!==null&&(!Number.isFinite(record.weight)||record.weight<0||record.weight>500)){$('logError').textContent='세트는 1–10, 횟수는 1–100, 중량은 0–500 범위로 입력해주세요.';return}}else{record.minutes=Number($('logMinutes').value);if(!Number.isInteger(record.minutes)||record.minutes<1||record.minutes>240){$('logError').textContent='운동 시간은 1–240분 범위의 정수로 입력해주세요.';return}}const a=active(),date=form.dataset.date;a.logs[date]??={};a.logs[date][form.dataset.exercise]=record;persist();closeDialog();render();savedToast('실제 수행 기록을 저장했어요.')}});
